import unittest
from settings import apply_defaults

class TestApplyDefaults(unittest.TestCase):
    def test_falsy_values_precedence(self):
        # If 0 is in settings, it should NOT be replaced by the default 100
        settings = {"count": 0, "active": False, "name": ""}
        defaults = {"count": 100, "active": True, "name": "default"}

        result = apply_defaults(settings, defaults)

        # Current implementation would result in {"count": 100, "active": True, "name": "default"}
        # because 0, False, and "" are all falsy.
        # Expected result based on "take precedence": {"count": 0, "active": False, "name": ""}
        self.assertEqual(result, {"count": 0, "active": False, "name": ""})

