import unittest
from settings import apply_defaults

class TestApplyDefaults(unittest.TestCase):
    def test_falsy_values_precedence(self):
        # If 0, False, or "" are in settings, they should NOT be replaced by defaults
        settings = {"count": 0, "active": False, "name": ""}
        defaults = {"count": 10, "active": True, "name": "Default"}

        result = apply_defaults(settings, defaults)

        # Current implementation with 'if not result.get(key)' will overwrite 0, False, and ""
        # because they are all falsy.
        self.assertEqual(result["count"], 0, "0 should take precedence over default 10")
        self.assertEqual(result["active"], False, "False should take precedence over default True")
        self.assertEqual(result["name"], "", "Empty string should take precedence over default 'Default'")

