import unittest
from settings import apply_defaults

class TestApplyDefaults(unittest.TestCase):
    def test_none_precedence(self):
        # If 'None' is in settings, it should override the default value.
        # {**defaults, **settings} works because settings is unpacked last.
        settings = {"timeout": None, "retry": True}
        defaults = {"timeout": 30, "mode": "auto"}
        expected = {"timeout": None, "retry": True, "mode": "auto"}
        self.assertEqual(apply_defaults(settings, defaults), expected)

