function.description:
Write an async JavaScript function body using tools.* and return its JSON result explicitly. Use return null for an intentional empty result. Normal authorization applies. Calls return {ok:true, value} or {ok:false, error}; check ok. For const result = await tools.NAME(...), use result.value.text for read_file and result.value.matches for grep (possibly an empty array). Await all tool/store/load calls. console.log/error fail; only return delivers data. No direct filesystem, process, network, shell or recursive CodeMode access. Preserve argument strings exactly, including whether quote characters are present. Put task data (paths, search queries, file contents) in inputs, not JS string literals. Read it as inputs.name; inputs is immutable JSON data, never executable source. Example inputs={"path": "app.py"}; JavaScript: const result = await tools.read_file({path:inputs.path}); if (!result.ok) throw new Error(result.error); return result.value.text;
Multiline data arguments: {"code": "return inputs.text;", "inputs": {"text": "first\nsecond\n"}}
// tools.NAME uses NAME's declared arguments; returns Result<T>.
type Result<T> = Promise<{ok:true;value:T;result_ref?:string}|{ok:false;error:string}>;
declare const tools: {
  // edit.content: Complete file text; preserve unrelated content. Prefer replacements for focused edits.
  // edit.base_result_ref: Only for content mode; omit this field with replacements. Use the latest complete read_file receipt reference. In CodeMode pass readResult.result_ref, not readResult.value.result_ref; value contains file data.
  edit(args: { "path": string; "content"?: string; "base_result_ref"?: string; "replacements"?: Array<{ "old_string": string; "new_string": string }> }): Result<string>;
  find_references(args: { "symbol": string; "path"?: string }): Result<string>;
  // grep.include: One rg glob string, not an array. Combine alternatives with braces, e.g. *.{py,ts}.
  grep(args: { "query": string; "path"?: string; "offset"?: number /* range 1..* */; "limit"?: number /* range 1..* */; "literal"?: boolean; "case_sensitive"?: boolean; "include"?: string; "exclude"?: Array<string>; "before_context"?: number /* range 0..* */; "after_context"?: number /* range 0..* */ }): Result<{ "query": string; "path": string; "include": string; "exclude": Array<string>; "literal": boolean; "case_sensitive": boolean; "has_more": boolean; "scan_complete": boolean; "offset": number /* range 1..* */; "limit": number /* range 1..* */; "before_context": number /* range 0..* */; "after_context": number /* range 0..* */; "next_offset": number /* range 0..* */; "matches": Array<{ "path": string; "text": string; "line": number /* range 1..* */; "column_byte": number /* range 1..* */ }>; "context": Array<{ "path": string; "text": string; "line": number /* range 1..* */; "relation": "before" | "after" | "between" }>; "coverage": { "files_admitted": number /* range 0..* */; "bytes_admitted": number /* range 0..* */; "oversized": number /* range 0..* */; "unreadable": number /* range 0..* */; "budget_limited": boolean } }>;
  knowledge_read(args: { "id": string; "revision"?: number; "offset"?: number /* range 0..* */; "limit"?: number /* range 500..12000 */; "question_ref"?: string /* pattern "^q[1-8]$" */ }): Result<string>;
  knowledge_search(args: { "query": string; "depth"?: number; "question_ref"?: string /* pattern "^q[1-8]$" */ }): Result<string>;
  list_dir(args: { "path"?: string }): Result<string>;
  read_file(args: { "path": string; "offset"?: number /* range 1..* */; "limit"?: number /* range 1..* */ }): Result<{ "path": string; "text": string; "start_line": number /* range 1..* */; "end_line": number /* range 0..* */; "total_lines": number /* range 0..* */; "next_offset": number /* range 0..* */; "text_complete": boolean }>;
  research_plan(args: { "questions": Array<string> /* items 1..8 */ }): Result<string>;
};
